const GOOD = await rgb(good), BAD = await rgb(bad);

await ev(`document.querySelector('#add').click()`);
await sleep(350);
const asEvent = await ev(ROW);
ok('a new entry is an event', !asEvent.some(g => /^S@|^P$|^1d$/.test(g)),
